data ActionsObservation = ActionsObservation
  { epoch :: Integer
  , head :: Text
  , runId :: Text
  , attempt :: Integer
  , conclusion :: ActionsConclusion
  , fingerprint :: Text
  , capabilityAvailable :: Bool
  , observation :: Text
  , operation :: Text
  , baseHead :: Text
  , policyDigest :: Text
  }
  deriving stock (Eq, Show)

instance Contract ActionsObservation where
  contract =
    normalizing settleObservation $
      recordWith "ActionsObservation" positional $
        ActionsObservation
          <$> field "epoch" (.epoch) integer
          <*> field "head" (.head) text
          <*> field "run_id" (.runId) text
          <*> field "attempt" (.attempt) integer
          <*> field "conclusion" (.conclusion) contract
          <*> fieldDefault "fingerprint" (.fingerprint) "" text
          <*> fieldDefault "capability_available" (.capabilityAvailable) True bool
          <*> fieldDefault "observation" (.observation) "" text
          <*> fieldDefault "operation" (.operation) "" text
          <*> fieldDefault "base_head" (.baseHead) "" text
          <*> fieldDefault "policy_digest" (.policyDigest) "" text
      where
        positional = \case
          [(_, v0), (_, v1), (_, v2), (_, v3), (_, v4), (_, v5), (_, v6), (_, v7), (_, v8), (_, v9), (_, v10)] ->
            Just $
              ActionsObservation
                <$> member "epoch" integer v0
                <*> member "head" text v1
                <*> member "run_id" text v2
                <*> member "attempt" integer v3
                <*> member "conclusion" contract v4
                <*> member "fingerprint" text v5
                <*> member "capability_available" bool v6
                <*> member "observation" text v7
                <*> member "operation" text v8
                <*> member "base_head" text v9
                <*> member "policy_digest" text v10
          _ -> Nothing


-- | @ActionsObservation.__post_init__@: an empty @observation@ becomes
-- @"{run_id}:{attempt}:{conclusion}"@, so no observation is ever empty.
settleObservation :: ActionsObservation -> ActionsObservation
settleObservation value
  | T.null value.observation =
      ActionsObservation
        { epoch = value.epoch
        , head = value.head
        , runId = value.runId
        , attempt = value.attempt
        , conclusion = value.conclusion
        , fingerprint = value.fingerprint
        , capabilityAvailable = value.capabilityAvailable
        , observation = value.runId <> ":" <> T.pack (show value.attempt) <> ":" <> spelling value.conclusion
        , operation = value.operation
        , baseHead = value.baseHead
        , policyDigest = value.policyDigest
        }
  | otherwise = value

